pages.content:
{
  "category": "api",
  "changes": [
    {
      "statement": "Removed the payment_intent field from the Invoice object.",
      "handling": "ai",
      "family": "read-review",
      "identifiers": ["invoice.payment_intent"],
      "rationale": "The page removes the single-payment pointer and directs integrations to invoice.payments and Invoice Payment objects. A collection of payments is not an exact one-to-one replacement."
    },
    {
      "statement": "Removed the charge field from the Invoice object.",
      "handling": "ai",
      "family": "read-review",
      "identifiers": ["invoice.charge"],
      "rationale": "The page explicitly removes charge as part of replacing previous invoice and payment pointers. It provides no exact replacement for this field."
    },
    {
      "statement": "Removed the paid field from the Invoice object.",
      "handling": "ai",
      "family": "read-review",
      "identifiers": ["invoice.paid"],
      "rationale": "The page explicitly lists paid among the removed Invoice fields without naming an exact replacement."
    },
    {
      "statement": "Removed the paid_out_of_band field from the Invoice object.",
      "handling": "ai",
      "family": "read-review",
      "identifiers": ["invoice.paid_out_of_band"],
      "rationale": "The page describes identifying out-of-band payments using payment records or, in later versions, amount_paid_off_stripe. These require conditional calculations rather than a same-value field substitution."
    },
    {
      "statement": "Removed the invoice field from the PaymentIntent object.",
      "handling": "ai",
      "family": "read-review",
      "identifiers": ["payment_intent.invoice"],
      "rationale": "The page removes invoice and recommends the List Invoice Payment endpoint to understand the connection between PaymentIntent and Invoice objects. An endpoint lookup is not an exact replacement field."
    },
    {
      "statement": "Removed the invoice field from the Charge object.",
      "handling": "ai",
      "family": "read-review",
      "identifiers": ["charge.invoice"],
      "rationale": "The page explicitly removes the invoice pointer from Charge without naming an exact replacement field."
    },
    {
      "statement": "Removed application_fee_amount from the Invoice object; for payments made on Stripe, it is accessible through payments.data[i].payment.payment_intent.application_fee_amount.",
      "handling": "ai",
      "family": "read-review",
      "identifiers": [
        "invoice.application_fee_amount",
        "invoice.payments.data.payment.payment_intent.application_fee_amount"
      ],
      "rationale": "The replacement access is through individual payments and is available only when the payment type is payment_intent. This is not an unconditional one-to-one move of the Invoice field."
    },
    {
      "statement": "Removed transfer_data from the Invoice object; for payments made on Stripe, it is accessible through payments.data[i].payment.payment_intent.transfer_data.",
      "handling": "ai",
      "family": "read-review",
      "identifiers": [
        "invoice.transfer_data",
        "invoice.payments.data.payment.payment_intent.transfer_data"
      ],
      "rationale": "The page limits this access to underlying PaymentIntents for payments made on Stripe. Selecting from multiple payments requires review rather than a deterministic field move."
    },
    {
      "statement": "Replaced the Credit Note object's refund field with a refunds array.",
      "handling": "ai",
      "family": "read-review",
      "identifiers": ["credit_note.refund", "credit_note.refunds"],
      "rationale": "The prose calls refund deprecated, while the change tables list it as removed. Replacing a single refund with an array does not provide an exact same-value field replacement."
    },
    {
      "statement": "The Invoice object's amount_paid field now reflects out-of-band payments.",
      "handling": "none",
      "family": "none",
      "identifiers": ["invoice.amount_paid"],
      "rationale": "The page changes what amount_paid includes, rather than describing a schema change. OpenAPI comparison cannot trace this semantic change."
    },
    {
      "statement": "Removed the refund request parameter from CreditNote#create, CreditNote#preview_lines, and CreditNote#preview, adding refunds instead.",
      "handling": "stop",
      "family": "none",
      "identifiers": [
        "POST /v1/credit_notes refund",
        "GET /v1/credit_notes/preview/lines refund",
        "GET /v1/credit_notes/preview refund"
      ],
      "rationale": "The change tables remove refund and add refunds for these requests. The page describes refunds as an array, not an exact same-value rename or wrapper."
    },
    {
      "statement": "Added invoice.overpaid to the enabled_events enums for WebhookEndpoint#create and WebhookEndpoint#update and to the Event.type enum.",
      "handling": "generic",
      "family": "none",
      "identifiers": [
        "POST /v1/webhook_endpoints enabled_events",
        "POST /v1/webhook_endpoints/{id} enabled_events",
        "event.type"
      ],
      "rationale": "The change tables explicitly add invoice.overpaid to these enums. OpenAPI comparison can report the enum expansion, including its impact on code comparing or switching over Event.type."
    }
  ]
}

{
  "category": "api",
  "changes": [
    {
      "statement": "Subscriptions for subscription-mode Checkout Sessions are now created after the user completes payment.",
      "handling": "none",
      "family": "none",
      "identifiers": [],
      "rationale": "The page states that subscription creation now happens after payment completes. This is a lifecycle timing change, not a contract change Refit can trace."
    },
    {
      "statement": "A payment_intent no longer references an invoice until the Checkout Session fully completes and checkout.session.status is complete.",
      "handling": "none",
      "family": "none",
      "identifiers": [
        "checkout.session.status"
      ],
      "rationale": "The page says an invoice is not created until the Session completes and recommends using checkout_session.completed instead of payment intent webhooks when an invoice is required. This changes availability timing rather than removing or moving a contract field."
    },
    {
      "statement": "Failed payment attempts no longer result in an incomplete subscription with a finalized invoice.",
      "handling": "none",
      "family": "none",
      "identifiers": [],
      "rationale": "The Impact section explicitly describes this change to the objects created after a failed payment attempt. It is a behavioral change without an OpenAPI contract signal."
    }
  ]
}

{
  "category": "stripejs",
  "changes": [
    {
      "statement": "The Payment Element default layout changes from `tabs` to `accordion`.",
      "handling": "none",
      "family": "none",
      "identifiers": [],
      "rationale": "The page says the Payment Element now defaults to `accordion` and recommends explicitly setting the layout to `tabs` or adapting the design. This is a browser-library change, not a server OpenAPI contract change."
    },
    {
      "statement": "The Payment Element now collapses when multiple payment methods are displayed and `defaultCollapsed` is undefined.",
      "handling": "none",
      "family": "none",
      "identifiers": [
        "Payment Element.defaultCollapsed"
      ],
      "rationale": "The page changes the behavior of an undefined `defaultCollapsed` value and says setting it to true restores the previous behavior. This Payment Element behavior is outside the server OpenAPI contract."
    }
  ]
}

{
  "category": "api",
  "changes": [
    {
      "statement": "PaymentIntents using the `interac_present` payment method type no longer support `capture_method=manual` and must use `automatic_async` or `automatic` instead.",
      "handling": "none",
      "family": "none",
      "identifiers": [
        "payment_intent.capture_method",
        "POST /v1/payment_intents capture_method"
      ],
      "rationale": "The page removes manual capture support specifically for `interac_present`, while retaining manual capture for `card_present` through `payment_method_options.card_present.capture_method`. This is a payment-method-dependent behavior restriction, not removal of the `manual` value from the capture-method contract."
    }
  ]
}

{
  "category": "api",
  "changes": [
    {
      "statement": "Subscription-level current_period_start and current_period_end are removed; access the subscription item’s billing periods through items.data.current_period_start and items.data.current_period_end instead.",
      "handling": "rule",
      "family": "period-helper",
      "identifiers": [
        "subscription.current_period_start",
        "subscription.current_period_end",
        "subscription_item.current_period_start",
        "subscription_item.current_period_end"
      ],
      "rationale": "The page explicitly replaces the subscription-level billing periods with billing periods on subscription items and names the item paths to use."
    },
    {
      "statement": "The customer.subscription.updated webhook’s previous_attributes now includes subscription-item billing-period changes, and integrations must inspect item-level previous attributes for changes such as price or quantity.",
      "handling": "none",
      "family": "none",
      "identifiers": [
        "customer.subscription.updated.previous_attributes",
        "customer.subscription.updated.previous_attributes.items.data[].price"
      ],
      "rationale": "The page describes changed contents of previous_attributes and directs integrations to inspect previous_attributes.items.data[].price; this is a webhook payload behavior change rather than a named contract-field replacement."
    }
  ]
}

{
  "category": "api",
  "changes": [
    {
      "statement": "List API methods no longer allow total_count expansion through include[]=total_count or exclude[]=total_count, and new users cannot expand total_count on earlier Stripe versions either.",
      "handling": "stop",
      "family": "none",
      "identifiers": [],
      "rationale": "The page prohibits requesting total_count expansion and says attempts return a 400 property_forbidden error. Integrations must instead rely on has_more, which requires changing pagination logic rather than substituting an equivalent parameter or value."
    }
  ]
}

{
  "category": "api",
  "changes": [
    {
      "statement": "The GET /v1/invoices/upcoming endpoint and the upcoming method are removed in favor of the Create Preview Invoice API.",
      "handling": "stop",
      "family": "none",
      "identifiers": [
        "GET /v1/invoices/upcoming"
      ],
      "rationale": "The page removes the endpoint and method and directs integrations to the Create Preview Invoice API; this is an operation replacement, not a parameter rename or wrapper edit."
    },
    {
      "statement": "The Create Preview Invoice API no longer previews a customer's next invoice across all subscriptions and requires subscription, subscription_details.items, schedule, schedule_details.phases, or invoice_items along with customer.",
      "handling": "none",
      "family": "none",
      "identifiers": [],
      "rationale": "The page describes a behavioral restriction on customer-only previews and a conditional requirement to supply one of several inputs, rather than a directly traceable field removal or rename."
    },
    {
      "statement": "The GET /v1/invoices/upcoming/lines endpoint and the upcomingLines method are removed in favor of the Create Preview Invoice API.",
      "handling": "stop",
      "family": "none",
      "identifiers": [
        "GET /v1/invoices/upcoming/lines"
      ],
      "rationale": "The Impact section directs users away from this endpoint, and the tables explicitly mark upcomingLines as removed; migrating the operation requires review."
    }
  ]
}

{
  "category": "api",
  "changes": [
    {
      "statement": "Tax Rate IDs on Invoice Line Items and Credit Note Line Items move from tax_rates entries to taxes entries under tax_rate_details.tax_rate, after verifying that the entry's type is tax_rate_details.",
      "handling": "rule",
      "family": "moved-id",
      "identifiers": [
        "invoice_line_item.tax_rates",
        "invoice_line_item.taxes",
        "credit_note_line_item.tax_rates",
        "credit_note_line_item.taxes"
      ],
      "rationale": "The Impact section explicitly replaces line_item.tax_rates[0] with line_item.taxes[0].tax_rate_details.tax_rate and requires checking the entry's type."
    },
    {
      "statement": "On Invoice Line Items and Credit Note Line Items, tax_amounts entries' amount values move to taxes entries' amount values.",
      "handling": "rule",
      "family": "moved-value",
      "identifiers": [
        "invoice_line_item.tax_amounts.amount",
        "invoice_line_item.taxes.amount",
        "credit_note_line_item.tax_amounts.amount",
        "credit_note_line_item.taxes.amount"
      ],
      "rationale": "The page explicitly instructs replacing line_item.tax_amounts[0].amount with line_item.taxes[0].amount for these line items."
    },
    {
      "statement": "The remaining reads of tax_amounts on Invoice Line Items and Credit Note Line Items lose that response field without an exact replacement specified.",
      "handling": "ai",
      "family": "read-review",
      "identifiers": [
        "invoice_line_item.tax_amounts",
        "credit_note_line_item.tax_amounts"
      ],
      "rationale": "The page removes tax_amounts from both objects, but its exact replacement example covers only the amount value, not every use of the removed field."
    },
    {
      "statement": "On Invoice objects, total_tax_amounts entries' amount values move to total_taxes entries' amount values, after verifying that the entry's type is tax_rate_details.",
      "handling": "rule",
      "family": "moved-value",
      "identifiers": [
        "invoice.total_tax_amounts.amount",
        "invoice.total_taxes.amount",
        "invoice.total_taxes.type"
      ],
      "rationale": "The Impact section explicitly replaces invoice.total_tax_amounts[0].amount with invoice.total_taxes[0].amount, subject to the stated type check."
    },
    {
      "statement": "The remaining reads of total_tax_amounts on Invoice objects lose that response field without an exact replacement specified.",
      "handling": "ai",
      "family": "read-review",
      "identifiers": [
        "invoice.total_tax_amounts"
      ],
      "rationale": "The page removes total_tax_amounts, but the exact migration example only maps its entries' amount values."
    },
    {
      "statement": "CreditNote objects no longer expose tax_amounts.",
      "handling": "ai",
      "family": "read-review",
      "identifiers": [
        "credit_note.tax_amounts"
      ],
      "rationale": "The Changes table removes CreditNote.tax_amounts and adds total_taxes, but the page does not specify an exact field-by-field replacement for CreditNote.tax_amounts."
    },
    {
      "statement": "CreditNoteLineItem and InvoiceLineItem objects no longer expose amount_excluding_tax or unit_amount_excluding_tax.",
      "handling": "ai",
      "family": "read-review",
      "identifiers": [
        "credit_note_line_item.amount_excluding_tax",
        "credit_note_line_item.unit_amount_excluding_tax",
        "invoice_line_item.amount_excluding_tax",
        "invoice_line_item.unit_amount_excluding_tax"
      ],
      "rationale": "The Changes tables mark both properties as removed from both line item objects and provide no replacements."
    },
    {
      "statement": "Invoice objects no longer expose tax.",
      "handling": "ai",
      "family": "read-review",
      "identifiers": [
        "invoice.tax"
      ],
      "rationale": "The Changes tables list tax as removed from Invoice without specifying an exact replacement."
    }
  ]
}

{
  "category": "api",
  "changes": [
    {
      "statement": "Issuing.Authorization.status adds the enum value `expired` for authorizations expired by Stripe instead of reporting `reversed`, and Issuing.AuthorizationListParams.status adds the same value.",
      "handling": "generic",
      "family": "none",
      "identifiers": [
        "Issuing.Authorization.status",
        "Issuing.AuthorizationListParams.status"
      ],
      "rationale": "The page explicitly adds `expired` to the authorization status and list status enums. This is a contract-visible enum addition that requires reviewing status comparisons, not a one-to-one replacement of `reversed`, which remains applicable to authorizations reversed by the acquiring business."
    }
  ]
}

{
  "category": "api",
  "changes": [
    {
      "statement": "The naver_pay parameter is removed from PaymentMethod updates (POST /v1/payment_methods/:id and PaymentMethodUpdateParams), so Naver Pay parameters can only be set when creating a PaymentMethod.",
      "handling": "stop",
      "family": "none",
      "identifiers": [
        "POST /v1/payment_methods/:id naver_pay"
      ],
      "rationale": "The page explicitly removes naver_pay from PaymentMethod updates and says it can only be set during creation. It provides no replacement parameter for updating an existing PaymentMethod."
    }
  ]
}

{
  "category": "api",
  "changes": [
    {
      "statement": "Adds `network_fallback` to the Issuing authorization object's `request_history.reason` options.",
      "handling": "generic",
      "family": "none",
      "identifiers": [
        "issuing_authorization.request_history.reason"
      ],
      "rationale": "The REST API and Node.js change tables explicitly identify `network_fallback` as an added enum value for `Issuing.Authorization.request_history[].reason`. The page warns that code expecting a fixed set of options must account for this new value."
    }
  ]
}

{
  "category": "api",
  "changes": [
    {
      "statement": "Creating or updating a Person now requires political_exposure to be 'existing' or 'none' rather than an arbitrary string, including Token#create.person.political_exposure and TokenCreateParams.person.political_exposure.",
      "handling": "stop",
      "family": "none",
      "identifiers": [
        "person.political_exposure",
        "Token#create.person.political_exposure",
        "TokenCreateParams.person.political_exposure"
      ],
      "rationale": "The page says values outside the political exposure enum can no longer be assigned and lists the token creation parameter changing from string to enum('existing'|'none'). It provides no exact replacement for invalid values."
    },
    {
      "statement": "The Person object's political_exposure property now uses enum values rather than an unrestricted string, affecting code that expects values outside that enum.",
      "handling": "generic",
      "family": "none",
      "identifiers": [
        "person.political_exposure"
      ],
      "rationale": "The page states that the Person property changes from a string to an enum and explicitly calls out code expecting a Person to have an invalid political_exposure value. This is a response contract change, not a field removal or move."
    }
  ]
}

{
  "category": "api",
  "changes": [
    {
      "statement": "Partial capture and payment cancellation, both manual and automated, no longer create a Refund representing the cancellation or capture reversal, so it is absent from refund listings, webhook events, Charge API responses, and the Dashboard.",
      "handling": "none",
      "family": "none",
      "identifiers": [],
      "rationale": "The page describes Refund objects no longer being created for these flows, not removal of a Refund schema or a response field from the contract."
    },
    {
      "statement": "PaymentIntent.cancellation_reason adds expired and uses it instead of automatic for payments canceled because of authorization expiration.",
      "handling": "generic",
      "family": "none",
      "identifiers": [
        "payment_intent.cancellation_reason"
      ],
      "rationale": "The page explicitly lists expired as an added enum value and explains when it replaces automatic; this is not a universal one-to-one replacement of automatic."
    },
    {
      "statement": "Charge.amount_captured is now 0 instead of nil in payment cancellation flows.",
      "handling": "none",
      "family": "none",
      "identifiers": [
        "charge.amount_captured"
      ],
      "rationale": "The page describes a flow-specific change in the returned value, not an explicit change to the field's contract."
    },
    {
      "statement": "Charge.amount_refunded is no longer updated by partial capture or payment cancellation.",
      "handling": "none",
      "family": "none",
      "identifiers": [
        "charge.amount_refunded"
      ],
      "rationale": "The field remains present; the page changes when its value is updated rather than its contract."
    },
    {
      "statement": "Charge.refunded is no longer true for payment cancellation flows.",
      "handling": "none",
      "family": "none",
      "identifiers": [
        "charge.refunded"
      ],
      "rationale": "The page describes changed boolean behavior for payment cancellation, not removal or replacement of the field."
    },
    {
      "statement": "Partial captures now have only one balance transaction and no longer have a balance transaction representing the amount and fees reversed.",
      "handling": "none",
      "family": "none",
      "identifiers": [],
      "rationale": "The page changes which balance transactions are created, without naming a schema property or contract change."
    },
    {
      "statement": "The balance transaction representing the capture now shows the amount captured instead of the amount authorized for the related payment.",
      "handling": "none",
      "family": "none",
      "identifiers": [],
      "rationale": "The page describes a change in the meaning of the returned amount, not a field move or another explicit contract change."
    },
    {
      "statement": "Stripe no longer sends charge.refunded and charge.refund.updated webhook events for partial capture and payment cancellation flows.",
      "handling": "none",
      "family": "none",
      "identifiers": [],
      "rationale": "The page changes event delivery for these flows, not the webhook event contract."
    },
    {
      "statement": "A Radar payment review closed upon payment cancellation now has Review.closed_reason set to the newly added canceled value instead of refunded.",
      "handling": "generic",
      "family": "none",
      "identifiers": [
        "review.closed_reason"
      ],
      "rationale": "The page explicitly lists canceled as an added Review.closed_reason enum value and describes its use upon payment cancellation."
    }
  ]
}

{
  "category": "api",
  "changes": [
    {
      "statement": "Creating coupons that combine amount_off with duration: 'forever' is no longer supported.",
      "handling": "none",
      "family": "none",
      "identifiers": [
        "coupon.amount_off",
        "coupon.duration"
      ],
      "rationale": "The page prohibits this combination, rather than removing amount_off or the forever duration value independently. This is a behavioral restriction without a stated OpenAPI contract change."
    },
    {
      "statement": "Existing indefinite amount_off coupons and their related promotion codes can no longer be applied to subscriptions, subscription items, subscription schedules, invoices, invoice items, quotes, Checkout Sessions created with API version 2025-03-31.basil or later, Payment Links created in the Dashboard or with that API version or later, or pricing tables created in the Dashboard.",
      "handling": "none",
      "family": "none",
      "identifiers": [],
      "rationale": "The page restricts which existing coupons and promotion codes can be used with these resources. It does not identify a removed request parameter or contract value, so this eligibility restriction has no stated contract signal to trace."
    }
  ]
}

{
  "category": "api",
  "changes": [
    {
      "statement": "The Discount coupon reference moves from coupon to source.coupon inside the new source hash.",
      "handling": "rule",
      "family": "moved-id",
      "identifiers": [
        "discount.coupon",
        "discount.source.coupon"
      ],
      "rationale": "The page removes Discount.coupon and introduces source.coupon as the Coupon redeemed to create the discount. Coupon identity reads can migrate to the new reference."
    },
    {
      "statement": "Coupon details are no longer automatically expanded on Discount objects, including within event notifications.",
      "handling": "ai",
      "family": "read-review",
      "identifiers": [
        "discount.coupon",
        "discount.source.coupon"
      ],
      "rationale": "The removed coupon property supplied an automatically expanded Coupon, whereas obtaining its details now requires a separate retrieval or expansion through source. Reads of those details therefore have no unconditional same-value replacement and require review."
    }
  ]
}

{
  "category": "api",
  "changes": [
    {
      "statement": "For new subscription schedules created without an explicit phase end_date, the end_date calculation now considers billing_cycle_anchor changes in addition to interval, interval_count, and the previous phase’s end_date.",
      "handling": "none",
      "family": "none",
      "identifiers": [
        "subscription_schedule.phases.end_date"
      ],
      "rationale": "The page describes a change to the automatically calculated end_date, not to the contract, so OpenAPI comparison cannot trace it. It applies only to new subscription schedules and does not affect existing schedules."
    }
  ]
}

{
  "category": "api",
  "changes": [
    {
      "statement": "New subscriptions created through the API now default to flexible billing mode rather than classic, affecting subscription creation, invoice previews, subscription schedules, quotes, Checkout Sessions, and Payment Links.",
      "handling": "none",
      "family": "none",
      "identifiers": [
        "subscription.billing_mode.type"
      ],
      "rationale": "The page says requests using API version 2025-09-30.clover or newer default to flexible billing mode, changing subscription behavior and invoice calculations; callers can explicitly set billing_mode.type to classic. This is a behavioral default change, not a removed or renamed contract field or value."
    }
  ]
}

{
  "category": "stripejs",
  "changes": [
    {
      "statement": "Elements now rejects initialization with reused PaymentIntent or SetupIntent client secrets in `succeeded`, `canceled`, `processing`, `requires_capture`, or `requires_action` states with non-detachable payment methods (Boleto, knet, Oxxo, us_cash_voucher), returning validation errors instead of rendering a payment form.",
      "handling": "none",
      "family": "none",
      "identifiers": [
        "payment_intent.client_secret",
        "setup_intent.client_secret"
      ],
      "rationale": "The page introduces Intent-state validation when creating an Elements instance on API version 2025-09-30.clover or later. This is an Elements behavior change, not a server-side OpenAPI contract change Refit can trace."
    }
  ]
}

{
  "category": "stripejs",
  "changes": [
    {
      "statement": "Elements with Checkout Sessions now automatically enables saved payment method redisplay when a customer ID is passed and collection when saved_payment_method_options.payment_method_save is enabled, even if the corresponding client-side configuration is omitted from initCheckout().",
      "handling": "none",
      "family": "none",
      "identifiers": [
        "saved_payment_method_options.payment_method_save",
        "elementsOptions.savedPaymentMethod"
      ],
      "rationale": "The page changes Payment Element defaults for integrations that previously omitted explicit client-side saved payment method configuration. This is browser-library behavior, not a server OpenAPI contract change."
    }
  ]
}

{
  "category": "api",
  "changes": [
    {
      "statement": "Changes the decline codes reported in PaymentIntents’ last_payment_error.decline_code for Alma, Amazon Pay, Billie, Satispay, and South Korean payment methods to provide more granular decline reasons.",
      "handling": "none",
      "family": "none",
      "identifiers": [
        "payment_intent.last_payment_error.decline_code"
      ],
      "rationale": "The page says the updated decline codes appear in last_payment_error.decline_code and integrations relying on that field should be updated. Decline codes are plain strings, so this change provides no contract signal Refit can trace."
    }
  ]
}

{
  "category": "api",
  "changes": [
    {
      "statement": "Promotion Codes now reference Coupons through promotion.coupon instead of the top-level coupon field.",
      "handling": "rule",
      "family": "moved-id",
      "identifiers": [
        "promotion_code.coupon",
        "promotion_code.promotion.coupon"
      ],
      "rationale": "The page moves the Coupon reference into the polymorphic promotion hash and notes that promotion.coupon is not automatically expanded on retrieval."
    },
    {
      "statement": "Creating a Promotion Code now requires passing the coupon parameter inside promotion as promotion.coupon.",
      "handling": "rule",
